const defaultData={profile:{name:'Student',xp:0,streak:1,lastStudy:null,role:'student',examDate:'',dailyGoal:15,examProfile:'schools'},history:[],writing:[],speaking:[],words:[],settings:{support:'guided',largeText:false,dyslexia:false,sound:true},mockAttempts:[],achievements:[],studySessions:[],assignmentProgress:{},courseCompletions:{},notifications:[]};
let data=load();
let state={view:API.token?'home':'login',skill:null,level:1,idx:0,selected:null,checked:false,tab:'all',practiceMode:'normal',mockSkill:null,mockQuestions:[],mockIdx:0,mockAnswers:[],mockEndsAt:null,activeAssignmentId:null,sessionId:null,sessionCompleted:false};
