function load(){try{const raw=localStorage.getItem(userStoreKey())||localStorage.getItem(STORE)||localStorage.getItem(LEGACY_STORE)||'{}';const parsed=JSON.parse(raw);return {...structuredClone(defaultData),...parsed,profile:{...structuredClone(defaultData.profile),...(parsed.profile||{})},settings:{...structuredClone(defaultData.settings),...(parsed.settings||{})},achievements:parsed.achievements||[],studySessions:parsed.studySessions||[]}}catch(e){return structuredClone(defaultData)}}
let syncTimer=null;
function save(){localStorage.setItem(userStoreKey(),JSON.stringify(data));try{window.dispatchEvent(new CustomEvent('petquest:data-saved'))}catch(_){}if(API.token){clearTimeout(syncTimer);syncTimer=setTimeout(()=>apiRequest('/snapshot',{method:'POST',body:{snapshot:data}}).catch(()=>{}),350)}}
function clearAuthSession(){API.token='';API.user=null;API.courses=[];API.assignments=[];API.sessionExpiresAt='';localStorage.removeItem('petQuestToken');localStorage.removeItem('petQuestSessionExpiresAt');localStorage.removeItem('petquest_token');localStorage.removeItem('token');}
const _apiInflight=new Map();
let _bootstrapPromise=null;
async function apiRequest(path,opt={}){
  const method=String(opt.method||'GET').toUpperCase();
  const hadToken=!!API.token;
  const key=(method==='GET'||method==='HEAD')?`${method}:${path}`:null;
  if(key&&_apiInflight.has(key))return _apiInflight.get(key);
  const task=(async()=>{
    const headers={'Content-Type':'application/json',...(opt.headers||{})};
    if(API.token)headers.Authorization='Bearer '+API.token;
    const controller=new AbortController();
    const timeoutMs=Math.max(3000,Math.min(30000,Number(opt.timeoutMs||12000)));
    const timeout=setTimeout(()=>controller.abort(),timeoutMs);
    try{
      const url=API.base+path;
      const r=await fetch(url,{...opt,headers,signal:opt.signal||controller.signal,body:opt.body?JSON.stringify(opt.body):undefined});
      const contentType=(r.headers.get('content-type')||'').toLowerCase();
      const raw=await r.text();
      let j={};
      if(raw){
        if(contentType.includes('application/json')){
          try{j=JSON.parse(raw)}catch(_){throw new Error('api_invalid_json')}
        }else{
          try{j=JSON.parse(raw)}catch(_){
            const looksHtml=/^\s*<!doctype\s+html|^\s*<html/i.test(raw);
            if(looksHtml)throw new Error('api_html_response');
            throw new Error('api_invalid_response');
          }
        }
      }
      if(!r.ok){
        // Critical V46.30 fix: anonymous/background 401s must NEVER trigger a render loop.
        if(r.status===401&&path!='/login'&&hadToken){clearAuthSession();state.view='login';queueMicrotask(()=>render())}
        throw new Error(j.error||`api_error_${r.status}`);
      }
      if(method!=='GET'&&method!=='HEAD'&&API?.user?.role==='student'){
        try{setTimeout(()=>window.dispatchEvent(new CustomEvent('petquest:server-mutated',{detail:{path,method}})),0)}catch(_){}
      }
      return j;
    }catch(e){
      if(e&&e.name==='AbortError')throw new Error('api_timeout');
      throw e;
    }finally{clearTimeout(timeout)}
  })();
  if(key)_apiInflight.set(key,task);
  try{return await task}finally{if(key)_apiInflight.delete(key)}
}
async function _apiBootstrapOnce(){
  try{
    const h=await apiRequest('/health');
    API.online=!!h.ok;API.environment=h.environment||'unknown';API.demoSeedEnabled=!!h.multi_tenant?.demo_seed_enabled;API.demoAccountsAvailable=!!h.multi_tenant?.demo_accounts_available;
  }catch(e){
    API.online=false;
    if(!API.token) state.view='login';
    render();
    return;
  }
  if(API.token){
    try{
      const m=await apiRequest('/me');
      API.user=m.user;
      // V46.8: user isolation. Load the authenticated user's persisted snapshot before rendering.
      const sr=await apiRequest('/snapshot');
      if(sr && sr.snapshot && typeof sr.snapshot==='object'){
        data={...JSON.parse(JSON.stringify(defaultData)),...sr.snapshot};
        data.profile={...defaultData.profile,...(sr.snapshot.profile||{})};
      }else{
        data=JSON.parse(JSON.stringify(defaultData));
      }
      data.profile.name=API.user.name||data.profile.name;
      data.profile.role=API.user.role==='admin'?'school':API.user.role||data.profile.role;
      localStorage.setItem(userStoreKey(),JSON.stringify(data));
      const [c,a]=await Promise.all([apiRequest('/courses'),apiRequest('/assignments')]);
      API.courses=c.courses||[];
      API.assignments=a.assignments||[];
      if(state.view==='login') state.view='home';
    }catch(e){
      API.token='';
      API.user=null;
      localStorage.removeItem('petQuestToken');
      localStorage.removeItem('petquest_token');
      localStorage.removeItem('token');
      state.view='login';
    }
  }else{
    state.view='login';
  }
  render();
}
async function apiBootstrap(){
  if(_bootstrapPromise)return _bootstrapPromise;
  _bootstrapPromise=_apiBootstrapOnce();
  try{return await _bootstrapPromise}finally{_bootstrapPromise=null}
}
function esc(s=''){return String(s).replace(/[&<>"']/g,m=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#039;'}[m]))}
function pct(skill){const h=data.history.filter(x=>x.skill===skill);return h.length?Math.round(h.filter(x=>x.correct).length/h.length*100):0}
function accuracy(){return data.history.length?Math.round(data.history.filter(x=>x.correct).length/data.history.length*100):0}
function readiness(){const scores=['reading','listening'].map(pct);const practice=Math.min(100,data.history.length*4);const writing=data.writing.length?Math.min(100,Math.round(data.writing.reduce((s,x)=>s+x.score,0)/data.writing.length*5)):0;const speaking=data.speaking.length?Math.min(100,60+data.speaking.length*5):0;const known=scores.filter(Boolean);const base=known.length?known.reduce((a,b)=>a+b,0)/known.length:0;return Math.round(base*.45+writing*.2+speaking*.15+practice*.2)}
function weakFocus(){const wrong=data.history.filter(x=>!x.correct);if(!wrong.length)return 'Comienza con Reading nivel 1';const counts={};wrong.forEach(x=>counts[x.focus]=(counts[x.focus]||0)+1);return Object.entries(counts).sort((a,b)=>b[1]-a[1])[0][0]}
function qById(id){return [...BANK.reading,...BANK.listening].find(q=>q.id===id)}
function daysUntilExam(){if(!data.profile.examDate)return null;const d=new Date(data.profile.examDate+'T12:00:00'),now=new Date();return Math.ceil((d-now)/(86400000))}
function dueWords(){const now=Date.now();return data.words.filter(w=>!w.nextReview||new Date(w.nextReview).getTime()<=now)}
function streakUpdate(){const today=new Date().toISOString().slice(0,10),last=data.profile.lastStudy?data.profile.lastStudy.slice(0,10):null;if(!last)return;if(last===today)return;const y=new Date();y.setDate(y.getDate()-1);data.profile.streak=last===y.toISOString().slice(0,10)?(data.profile.streak||0)+1:1}
function unlockAchievements(){const defs=[['first10','Primeros pasos',()=>data.history.length>=10],['accuracy80','Precisión 80',()=>data.history.length>=10&&accuracy()>=80],['writer','Writer',()=>data.writing.length>=3],['speaker','Speaker',()=>data.speaking.length>=3],['mock','Mock Hero',()=>data.mockAttempts.length>=2],['xp250','250 XP',()=>data.profile.xp>=250]];defs.forEach(([id,title,ok])=>{if(ok()&&!data.achievements.some(a=>a.id===id))data.achievements.push({id,title,date:new Date().toISOString()})})}
function studyRecommendation(){const due=dueWords().length;if(due)return `Tienes ${due} repaso${due===1?'':'s'} vencido${due===1?'':'s'} en My Word Book.`;const d=daysUntilExam();if(d!==null&&d<=14)return `Faltan ${Math.max(0,d)} días para tu fecha objetivo: prioriza un Mock y ${weakFocus()}.`;return `Tu foco actual es ${weakFocus()}. Haz una sesión corta antes de avanzar.`}
function applySettings(){document.documentElement.classList.toggle('large-text',data.settings.largeText);document.documentElement.classList.toggle('dyslexia',data.settings.dyslexia)}
function el(html){document.getElementById('app').innerHTML=html;applySettings();bind()}
